<h4 class="mb-3">تأمین‌کنندگان</h4><form method="post" class="card card-body mb-3"><input type="hidden" name="_csrf" value="<?=\App\Core\Security::e(\App\Core\Security::csrf())?>"><div class="row g-2"><div class="col-md-2"><input name="code" class="form-control" placeholder="کد"></div><div class="col-md-3"><input name="name" class="form-control" placeholder="نام" required></div><div class="col-md-2"><input name="phone" class="form-control" placeholder="تلفن"></div><div class="col-md-3"><input name="email" class="form-control" placeholder="ایمیل"></div><div class="col-md-2"><button class="btn btn-primary w-100">ثبت</button></div></div><input name="contact_name" class="form-control mt-2" placeholder="نام تماس"><textarea name="notes" class="form-control mt-2" placeholder="توضیحات"></textarea></form><table class="table table-bordered"><thead><tr><th>کد</th><th>نام</th><th>تلفن</th><th>ایمیل</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($suppliers as $r):?><tr><td><?=\App\Core\Security::e($r['code'])?></td><td><?=\App\Core\Security::e($r['name'])?></td><td><?=\App\Core\Security::e($r['phone'])?></td><td><?=\App\Core\Security::e($r['email'])?></td><td><?=$r['is_active']?'فعال':'غیرفعال'?></td><td><?php if($r['is_active']):?><form method="post" action="/pricing/public/admin/suppliers/<?=(int)$r['id']?>" class="d-inline"><input type="hidden" name="_csrf" value="<?=\App\Core\Security::e(\App\Core\Security::csrf())?>"><input type="hidden" name="name" value="<?=\App\Core\Security::e($r['name'])?>"><input type="hidden" name="code" value="<?=\App\Core\Security::e($r['code'])?>"><input type="hidden" name="phone" value="<?=\App\Core\Security::e($r['phone'])?>"><input type="hidden" name="email" value="<?=\App\Core\Security::e($r['email'])?>"><input type="hidden" name="contact_name" value="<?=\App\Core\Security::e($r['contact_name'])?>"><input type="hidden" name="notes" value="<?=\App\Core\Security::e($r['notes'])?>"><button class="btn btn-sm btn-outline-primary">ذخیره</button></form><form method="post" action="/pricing/public/admin/suppliers/<?=(int)$r['id']?>/archive" class="d-inline"><input type="hidden" name="_csrf" value="<?=\App\Core\Security::e(\App\Core\Security::csrf())?>"><button class="btn btn-sm btn-outline-danger">غیرفعال</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table>